css:
.capstone-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.capstone-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.25);
    text-align: center;
}

.capstone-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.capstone-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1rem;
}

.capstone-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
    font-weight: 600;
}

.capstone-sim-briefing {
    background: linear-gradient(135deg, #fff9e6 0%, #fff3cd 100%);
    border-left: 5px solid #f0ad4e;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.capstone-sim-briefing h4 {
    margin: 0 0 10px 0;
    color: #856404;
    font-size: 1rem;
}

.capstone-sim-briefing #briefingText {
    color: #664d03;
    font-size: 0.95rem;
    line-height: 1.6;
}

.capstone-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.capstone-sim-secondary-cards {
    margin-bottom: 25px;
}

.capstone-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 18px 14px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #2c5f8a;
}

.capstone-sim-status-card:hover {
    transform: translateY(-4px);
}

.capstone-sim-card-revenue { border-top-color: #27ae60; }
.capstone-sim-card-share { border-top-color: #8e44ad; }
.capstone-sim-card-cash { border-top-color: #2980b9; }
.capstone-sim-card-income { border-top-color: #e67e22; }
.capstone-sim-card-eps { border-top-color: #16a085; }
.capstone-sim-card-price { border-top-color: #c0392b; }
.capstone-sim-card-debt { border-top-color: #e74c3c; }
.capstone-sim-card-equity { border-top-color: #3498db; }
.capstone-sim-card-brand { border-top-color: #9b59b6; }
.capstone-sim-card-innov { border-top-color: #1abc9c; }
.capstone-sim-card-cap { border-top-color: #7f8c8d; }
.capstone-sim-card-markets { border-top-color: #f39c12; }

.capstone-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.capstone-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #2c3e50;
}

.capstone-sim-controls {
    background: white;
    border-radius: 16px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.capstone-sim-controls h3 {
    margin: 0 0 20px 0;
    color: #1a3a5c;
    font-size: 1.2rem;
    border-bottom: 2px solid #eef2f7;
    padding-bottom: 10px;
}

.capstone-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
    margin-bottom: 25px;
}

.capstone-sim-decision-group {
    display: flex;
    flex-direction: column;
}

.capstone-sim-decision-group label {
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.capstone-sim-decision-group small {
    color: #888;
    font-size: 0.78rem;
    margin-top: 4px;
}

.capstone-sim-decision-group .form-control {
    border-radius: 8px;
    border: 2px solid #ddd;
    padding: 8px 12px;
    font-size: 1rem;
    transition: border-color 0.2s;
}

.capstone-sim-decision-group .form-control:focus {
    border-color: #2c5f8a;
    box-shadow: 0 0 0 3px rgba(44,95,138,0.15);
}

.capstone-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}

.capstone-sim-btn-row .btn-primary {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    border: none;
    border-radius: 10px;
    padding: 12px 30px;
    font-size: 1rem;
    font-weight: 600;
    box-shadow: 0 4px 12px rgba(26,58,92,0.3);
    transition: transform 0.2s, box-shadow 0.2s;
}

.capstone-sim-btn-row .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(26,58,92,0.4);
}

.capstone-sim-event-log {
    background: linear-gradient(135deg, #fdecea 0%, #f8d7da 100%);
    border-left: 5px solid #dc3545;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.capstone-sim-event-log h4 {
    margin: 0 0 10px 0;
    color: #721c24;
    font-size: 1rem;
}

.capstone-sim-event-log #eventLogText {
    color: #721c24;
    font-size: 0.95rem;
    line-height: 1.6;
}

.capstone-sim-history {
    background: white;
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
    overflow-x: auto;
}

.capstone-sim-history h4 {
    margin: 0 0 15px 0;
    color: #1a3a5c;
    font-size: 1rem;
}

.capstone-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.capstone-sim-chart-wrapper {
    background: white;
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
    min-height: 300px;
    position: relative;
}

@media (max-width: 768px) {
    .capstone-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .capstone-sim-decision-grid {
        grid-template-columns: 1fr;
    }
    .capstone-sim-charts {
        grid-template-columns: 1fr;
    }
    .capstone-sim-value {
        font-size: 1.2rem;
    }
}

