                    window.mySimulation.t('price_warning'), 'warning'
                );
                return false;
            }
            if (decisions.marketingBudget < 5 || decisions.marketingBudget > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }
            if (decisions.rdBudget < 0 || decisions.rdBudget > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rd_warning'), 'warning'
                );
                return false;
            }
            if (decisions.dividendRate < 0 || decisions.dividendRate > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('dividend_warning'), 'warning'
                );
                return false;
            }

            var ds = window.mySimulation.state.domainState;
            if (decisions.expansionTarget !== 'none' && ds.marketsEntered.indexOf(decisions.expansionTarget) !== -1) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('market_already_entered'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var q = state.currentPeriod;
            var eventMsg = '';

            // --- Update strategic assets ---
            ds.brandEquity += (d.marketingBudget - 15) * 0.25;
            ds.brandEquity = Math.max(10, Math.min(100, ds.brandEquity));

            ds.innovationScore += (d.rdBudget - 8) * 0.35;
            ds.innovationScore = Math.max(5, Math.min(100, ds.innovationScore));

            ds.salesForce += d.salesChange;
            ds.salesForce = Math.max(100, Math.min(1200, ds.salesForce));
            ds.workforce += d.salesChange;

            ds.capacity += Math.round(d.capexInvestment * 800);
            ds.totalCapex += d.capexInvestment;

            // --- Market expansion ---
            var expansionCost = 0;
            if (d.expansionTarget !== 'none' && ds.marketsEntered.indexOf(d.expansionTarget) === -1) {
                expansionCost = this.EXPANSION_COST[d.expansionTarget] || 0;
                if (q >= 10) {
                    expansionCost = Math.round(expansionCost * 0.85);
                    eventMsg += '<br>' + window.mySimulation.t('ev_trade');
                }
                ds.marketsEntered.push(d.expansionTarget);
                ds.marketQuarters[d.expansionTarget] = q;
            }

            // --- Event effects ---
            var cogsAdjust = 0;
            var demandAdjust = 0;
            var capacityPenalty = 1.0;
            var extraCost = 0;

            if (q === 3) {
                ds.sugarTaxActive = true;
                cogsAdjust += 0.03;
                eventMsg += '<br>' + window.mySimulation.t('ev_sugar');
            }
            if (ds.sugarTaxActive && q > 3) {
                cogsAdjust += 0.03;
            }

            if (q === 5) {
                if (d.capexInvestment < 10) {
                    capacityPenalty = 0.85;
                    eventMsg += '<br>' + window.mySimulation.t('ev_port_hit');
                } else {
                    eventMsg += '<br>' + window.mySimulation.t('ev_port_ok');
                }
                cogsAdjust += 0.05;
                eventMsg += '<br>' + window.mySimulation.t('ev_altsource');
            }

            if (q === 2 || q === 6) {
                demandAdjust += 0.02;
                eventMsg += '<br>' + window.mySimulation.t('ev_growth');
            }

            if (q === 7) {
                cogsAdjust += 0.05;
                eventMsg += '<br>' + window.mySimulation.t('ev_currency');
            }

            if (q === 8) {
                demandAdjust -= 0.015;
                eventMsg += '<br>' + window.mySimulation.t('ev_pricewar');
            }

            if (q >= 9) {
                if (d.marketingBudget >= 12) {
                    ds.sustainabilityCompliant = true;
                    extraCost += 2;
                    eventMsg += '<br>' + window.mySimulation.t('ev_sustain');
                } else {
                    if (!ds.sustainabilityCompliant) {
                        extraCost += 5;
                        ds.brandEquity -= 3;
                        eventMsg += '<br>' + window.mySimulation.t('ev_noncomp');
                    }
                }
            }

            if (q === 11) {
                demandAdjust -= 0.03;
                eventMsg += '<br>' + window.mySimulation.t('ev_recession');
            }

            // --- Demand calculation ---
            var priceMult = 1 + (100 - d.priceIndex) * 0.012;
            var brandMult = 0.7 + ds.brandEquity * 0.006;
            var salesMult = 0.8 + Math.min(ds.salesForce, 900) * 0.00035;
            var innovMult = 0.85 + ds.innovationScore * 0.003;

            var competitiveResponse = 1.0;
            if (ds.marketShareCentral > 12) {
                competitiveResponse = 1 - (ds.marketShareCentral - 12) * 0.015;
            }

            var demandFactor = priceMult * brandMult * salesMult * innovMult * competitiveResponse;
            demandFactor *= (1 + demandAdjust);
            demandFactor *= capacityPenalty;

            // --- Market growth ---
            var growthRate = this.MARKET_GROWTH['central'];
            ds.baseRevenue *= (1 + growthRate);

            // --- Revenue from home market ---
            var homeRevenue = ds.baseRevenue * demandFactor * (d.priceIndex / 100);

            // --- Revenue from entered markets ---
            var intlRevenue = 0;
            for (var m = 0; m < ds.marketsEntered.length; m++) {
                var mkt = ds.marketsEntered[m];
                var quartersIn = q - (ds.marketQuarters[mkt] || q);
                var mktSize = this.MARKET_SIZE[mkt] / 4;
                var mktPenetration = Math.min(0.06, 0.01 + quartersIn * 0.008);
                intlRevenue += mktSize * mktPenetration * (d.priceIndex / 100) * brandMult;
            }

            var totalRevenue = homeRevenue + intlRevenue;

            // --- Cost structure ---
            var baseCOGSratio = 0.55 + cogsAdjust;
            var cogs = totalRevenue * baseCOGSratio;
            var grossProfit = totalRevenue - cogs;

            var salesExpense = ds.salesForce * 0.02;
            var marketingExpense = d.marketingBudget;
            var rdExpense = d.rdBudget;
            var adminExpense = 5 + (ds.marketsEntered.length * 1.5);
            var totalOpex = salesExpense + marketingExpense + rdExpense + adminExpense + extraCost;

            var ebitda = grossProfit - totalOpex;
            var depreciation = 3 + ds.totalCapex * 0.015;
            var operatingIncome = ebitda - depreciation;

            var interestExpense = ds.debt * 0.055 / 4;
            var ebt = operatingIncome - interestExpense;
            var taxes = Math.max(0, ebt * 0.28);
            var netIncome = ebt - taxes;

            // --- Dividends and cash flow ---
            var dividends = 0;
            if (netIncome > 0) {
                dividends = netIncome * (d.dividendRate / 100);
            }

            var cashFlow = netIncome + depreciation - d.capexInvestment - expansionCost - dividends;
            ds.cash += cashFlow;

            // --- Auto-borrow if cash is negative ---
            if (ds.cash < 0) {
                var borrowAmount = Math.ceil(Math.abs(ds.cash) + 5);
                ds.debt += borrowAmount;
                ds.cash += borrowAmount;
                eventMsg += '<br>' + window.mySimulation.t('ev_borrow').replace('{n}', borrowAmount);
            }

            // --- Update equity ---
            ds.equity += (netIncome - dividends);
            ds.cumulativeNetIncome += netIncome;

            // --- Market share dynamics ---
            var shareShift = (demandFactor - 1) * 2.5;
            if (q === 8) shareShift -= 1.5;
            var noise = (Math.sin(q * 7.3 + d.priceIndex * 0.1) * 0.5);
            ds.marketShareCentral += shareShift + noise;
            ds.marketShareCentral = Math.max(3, Math.min(25, ds.marketShareCentral));

            // --- Valuation metrics ---
            var annualizedNI = netIncome * 4;
            var eps = annualizedNI / ds.sharesOutstanding;

            var growthFactor = 1;
            if (ds.revenueHistory.length > 0) {
                var prevRev = ds.revenueHistory[ds.revenueHistory.length - 1];
                if (prevRev > 0) {
                    growthFactor = totalRevenue / prevRev;
                }
            }
            ds.peMultiple = Math.max(8, Math.min(25, ds.peMultiple * (0.85 + growthFactor * 0.2)));
            if (netIncome < 0) ds.peMultiple *= 0.9;

            var sharePrice = Math.max(1, eps * ds.peMultiple);
            if (eps <= 0) sharePrice = Math.max(1, ds.equity / ds.sharesOutstanding * 0.5);

            var roe = ds.equity > 0 ? (annualizedNI / ds.equity * 100) : 0;
            var grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue * 100) : 0;
            var ebitdaMargin = totalRevenue > 0 ? (ebitda / totalRevenue * 100) : 0;
            var debtToEquity = ds.equity > 0 ? (ds.debt / ds.equity) : 999;
            var marketsActive = 1 + ds.marketsEntered.length;

            // platform score: same point scale getPerformanceSummary uses for the final verdict (cumulative profit, EPS, share, ROE, share price, markets active bands out of 100), recomputed each round from the running totals so it matches at the end
            var scoreVal = 0;
            if (ds.cumulativeNetIncome > 0) scoreVal += 20;
            if (ds.cumulativeNetIncome > 50) scoreVal += 15;
            if (eps > 5) scoreVal += 15;
            if (ds.marketShareCentral > 12) scoreVal += 15;
            if (roe > 15) scoreVal += 10;
            if (sharePrice > 80) scoreVal += 15;
            if (marketsActive > 2) scoreVal += 10;
            var overallScore = Math.max(0, Math.min(100, Math.round(scoreVal)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // --- Push to history ---
            ds.revenueHistory.push(Math.round(totalRevenue * 10) / 10);
            ds.shareHistory.push(Math.round(ds.marketShareCentral * 10) / 10);
            ds.netIncomeHistory.push(Math.round(netIncome * 10) / 10);
            ds.epsHistory.push(Math.round(eps * 100) / 100);
            ds.sharePriceHistory.push(Math.round(sharePrice * 100) / 100);
            ds.ebitdaHistory.push(Math.round(ebitda * 10) / 10);
            ds.lastEventMsg = eventMsg;

            var results = {
                period: q,
                revenue: Math.round(totalRevenue * 10) / 10,
                cogs: Math.round(cogs * 10) / 10,
                grossProfit: Math.round(grossProfit * 10) / 10,
                grossMargin: Math.round(grossMargin * 10) / 10,
                ebitda: Math.round(ebitda * 10) / 10,
                ebitdaMargin: Math.round(ebitdaMargin * 10) / 10,
                netIncome: Math.round(netIncome * 10) / 10,
                eps: Math.round(eps * 100) / 100,
                sharePrice: Math.round(sharePrice * 100) / 100,
                roe: Math.round(roe * 10) / 10,
                debtToEquity: Math.round(debtToEquity * 100) / 100,
                marketShare: Math.round(ds.marketShareCentral * 10) / 10,
                cash: Math.round(ds.cash * 10) / 10,
                dividends: Math.round(dividends * 10) / 10,
                marketsActive: 1 + ds.marketsEntered.length
            };

            // --- Show event log ---
            var evPanel = document.getElementById('eventLogPanel');
            var evText = document.getElementById('eventLogText');
            if (evPanel && evText) {
                if (eventMsg) {
                    evPanel.style.display = 'block';
                    evText.innerHTML = eventMsg;
                } else {
                    evPanel.style.display = 'none';
                    evText.innerHTML = '';
                }
            }

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return results;
        }

