        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var profits = history.map(function(r) { return r.results ? r.results.netIncome || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var totalProfit = profits.reduce(function(s, v) { return s + v; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastResult = history[history.length - 1].results || {};
            var finalEPS = lastResult.eps || 0;
            var finalSharePrice = lastResult.sharePrice || 0;
            var finalShare = lastResult.marketShare || 0;
            var finalROE = lastResult.roe || 0;

            var score = 0;
            if (totalProfit > 0) score += 20;
            if (totalProfit > 50) score += 15;
            if (finalEPS > 5) score += 15;
            if (finalShare > 12) score += 15;
            if (finalROE > 15) score += 10;
            if (finalSharePrice > 80) score += 15;
            if (lastResult.marketsActive > 2) score += 10;

            var performance = T('perf_needs');
            if (score >= 40) performance = T('perf_solid');
            if (score >= 60) performance = T('perf_strong');
            if (score >= 80) performance = T('perf_leader');
            if (score >= 95) performance = T('perf_exceptional');

            var insights = [];
            if (finalShare > 15) insights.push(T('ins_dominant'));
            if (finalShare < 8) insights.push(T('ins_erosion'));
            if (totalProfit > 80) insights.push(T('ins_profit'));
            if (totalProfit < 0) insights.push(T('ins_negprofit'));
            if (finalEPS > 6) insights.push(T('ins_eps'));
            if (lastResult.marketsActive >= 3) insights.push(T('ins_multi'));
            if (lastResult.debtToEquity > 1.5) insights.push(T('ins_leverage'));
            if (insights.length === 0) insights.push(T('ins_steady'));

            return {
                totalRevenue: Math.round(totalRevenue),
                totalProfit: Math.round(totalProfit * 10) / 10,
                avgQuarterlyProfit: Math.round(avgProfit * 10) / 10,
                finalEPS: finalEPS,
                finalSharePrice: finalSharePrice,
                finalMarketShare: finalShare,
                finalROE: Math.round(finalROE * 10) / 10,
                score: score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.netIncome < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.cash < 10) return window.mySimulation.t('hint_cash_low');
            if (results.marketShare < state.domainState.shareHistory[0] - 2) return window.mySimulation.t('hint_share_drop');
            if (results.ebitdaMargin > 15 && results.marketShare > 10) return window.mySimulation.t('hint_good_quarter');
            if (state.domainState.debt / state.domainState.equity > 1.2) return window.mySimulation.t('hint_leverage');
            return null;
        }

